insert into public.repair_tickets (id, company_id, tenancy_id, unit_id, category, priority, status, title, description, has_photo, created_at, resolved_at, assigned_to, resolution_note) values
  ('MT-1047', 'harborridge', 'L-2172', 'nr-312', 'plumbing', 'high', 'open', 'Kitchen sink leaking under cabinet', 'Leaking quite badly under the sink. A bucket is catching it for now.', true, '2026-10-06T07:40:00+03:00', null, null, null),
  ('MT-1046', 'harborridge', 'L-2166', 'nr-207', 'electrical', 'low', 'open', 'Corridor light out on 2nd floor', 'The corridor light outside 207 has been off for two nights.', false, '2026-10-05T19:12:00+03:00', null, null, null),
  ('MT-1044', 'harborridge', 'L-2150', 'rc-1c', 'plumbing', 'medium', 'in_progress', 'Water heater not heating', 'Shower water stays cold even after an hour.', false, '2026-09-28T08:05:00+03:00', null, 'Otieno Fundi Services', null),
  ('MT-1041', 'harborridge', 'L-2207', 'kh-a12', 'carpentry', 'low', 'in_progress', 'Balcony door lock stiff', 'The balcony door lock is hard to turn.', false, '2026-09-26T17:30:00+03:00', null, 'Otieno Ouma (caretaker)', null),
  ('MT-1039', 'harborridge', 'L-2160', 'rc-5a', 'electrical', 'high', 'resolved', 'Socket in bedroom sparks', 'The socket by the bed sparks when anything is plugged in.', true, '2026-09-22T21:10:00+03:00', '2026-09-24T11:00:00+03:00', 'Otieno Fundi Services', 'Socket and faceplate replaced.'),
  ('MT-1038', 'harborridge', 'L-2154', 'mg-2', 'security', 'medium', 'resolved', 'Gate remote not working', 'The gate remote stopped opening the main gate.', false, '2026-09-20T07:15:00+03:00', '2026-09-22T10:30:00+03:00', 'Achieng Atieno (caretaker)', 'Remote reprogrammed and battery replaced.'),
  ('MT-2002', 'savanna', 'SV-102', 'mc-3', 'plumbing', 'medium', 'open', 'Bathroom tap dripping', 'The bathroom tap drips all night.', false, '2026-10-04T20:15:00+03:00', null, null, null),
  ('MT-2001', 'savanna', 'SV-101', 'mc-1', 'electrical', 'low', 'resolved', 'Kitchen bulb holder loose', 'The bulb holder in the kitchen is hanging loose.', false, '2026-09-12T09:00:00+03:00', '2026-09-13T16:00:00+03:00', 'Kamau Ndirangu (caretaker)', 'Holder refitted.');
insert into public.messages (id, company_id, tenancy_id, sender, staff_id, body, sent_at, read_by_staff_at) values
  ('msg-101', 'harborridge', 'L-2172', 'tenant', null, 'Hi, the kitchen sink is leaking quite badly. I have put a bucket under it.', '2026-10-06T07:41:00+03:00', '2026-10-06T07:50:00+03:00'),
  ('msg-102', 'harborridge', 'L-2172', 'staff', 's-njoki', 'Thanks Lucy. I have logged it as MT-1047. A plumber will come by before noon.', '2026-10-06T07:55:00+03:00', null),
  ('msg-103', 'harborridge', 'L-2172', 'tenant', null, 'Okay, I will be home. Thank you.', '2026-10-06T08:02:00+03:00', null),
  ('msg-201', 'harborridge', 'L-2160', 'tenant', null, 'I sent the renewal back with a question about the 5% increase. Can we discuss?', '2026-10-05T18:20:00+03:00', '2026-10-06T09:05:00+03:00'),
  ('msg-202', 'harborridge', 'L-2160', 'staff', 's-njoki', 'Hi David, the increase matches the market review for Riverside Court. Happy to keep the deposit as is so nothing extra is due.', '2026-10-06T09:12:00+03:00', null),
  ('msg-301', 'harborridge', 'L-2185', 'tenant', null, 'I will clear half by Friday and the rest by the 20th.', '2026-10-05T20:45:00+03:00', null),
  ('msg-901', 'savanna', 'SV-102', 'tenant', null, 'Hello, the bathroom tap is dripping all night. Can someone look at it?', '2026-10-04T20:16:00+03:00', '2026-10-05T08:00:00+03:00'),
  ('msg-902', 'savanna', 'SV-102', 'staff', 's-wanjiru', 'Hi Naliaka, Kamau will pass by tomorrow morning to fix it.', '2026-10-05T08:10:00+03:00', null);
